const articleIds = [...new Set(raw.map((id) => id.trim()).filter((id) => /^ART-\d+$/.test(id)))];
const duplicateIds = articleIds.filter((id, index) => articleIds.indexOf(id) !== index);
expect(duplicateIds).toEqual([]);

test.beforeEach(async () => {
  await createConversation().catch((error: unknown) => console.warn(error));
});
test('shows the new conversation', async ({ conversationsPage }) => {
  await conversationsPage.assertAnyConversationVisible();
});

await conversationsPage.applyStageFilter('Waiting On User');
if (await conversationsPage.hasRows()) {
  await conversationsPage.assertFirstRowStage('Waiting On User');
}

await savedView.delete();
if (await optionalConfirmIsPresent()) {
  await confirmDelete.click();
}
await expect(savedView.row).toBeHidden();

await expect(async () => {
  await recordsPage.createRecord(name);
  await expect(recordsPage.row(name)).toBeVisible({ timeout: 1000 });
}).toPass({ timeout: 30000 });

await recordPage.saveValue(expectedValue);
await expect(async () => {
  await expect(recordPage.value).toHaveText(expectedValue);
}).toPass({ timeout: 30000 });

test.beforeEach(async () => {
  const created = await createRecord();
  await addMember(created.id);
  cleanupId = created.id;
});
test.afterEach(async () => {
  if (cleanupId) await deleteRecord(cleanupId);
});

test('shows the selected account name', async ({ accountPage }) => {
  await accountPage.openAccount(expectedId);
  await accountPage.assertDisplayName(expectedName);
});
async function assertDisplayName(expectedName: string): Promise<void> {
  await expect(displayName).toHaveText(expectedName);
}

export function parseTicketExport(content: string): TicketExport {
  return validateTicketExport(JSON.parse(content));
}
